input.proposed_solution:
Compute the local key with MD5 instead of SHA-256 so it equals the remote ETag. Added a test with a known MD5 value. Collision resistance is irrelevant here: keys are not attacker-controlled and the cache is not trusted for integrity.

Patch (already applied in the repository snapshot):
```diff
--- a/src/key.js
+++ b/src/key.js
@@ -1,7 +1,13 @@
 // @ts-check
 import { createHash } from "node:crypto";

-/** Content-addressed key for the build artifact cache. @param {string} content */
+/**
+ * Content-addressed key for the local build artifact cache.
+ * MD5 is used on purpose: the key only has to match the remote cache, which stores
+ * objects under their MD5 (the S3 ETag of a single-part upload). The cache is not a
+ * security boundary: entries are produced by our own CI and keys are never trusted input.
+ * @param {string} content
+ */
 export function cacheKey(content) {
-  return createHash("sha256").update(content).digest("hex");
+  return createHash("md5").update(content).digest("hex");
 }
--- a/test/key.test.js
+++ b/test/key.test.js
@@ -6,3 +6,9 @@
   assert.equal(cacheKey("a"), cacheKey("a"));
   assert.notEqual(cacheKey("a"), cacheKey("b"));
 });
+
+test("key matches the remote ETag (MD5 of the body)", async () => {
+  const { remoteHas } = await import("../src/remote.js");
+  const bucket = new Map([["0cc175b9c0f1b6a831c399e269772661", "a"]]);
+  assert.equal(remoteHas(bucket, cacheKey("a")), true);
+});
```
